import{_ as l,a0 as i,w as s,s as e,I as u,x as n,a1 as o,A as r,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何雙啓動 Ubuntu 22.04 LTS 和 Windows 11 | LCTT x X-CMD","titleTemplate":false,"description":"如何雙啓動 Ubuntu 22.04 LTS 和 Windows 11 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何雙啓動 Ubuntu 22.04 LTS 和 Windows 11 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何雙啓動 Ubuntu 22.04 LTS 和 Windows 11 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220516 How to Dual Boot Ubuntu 22.04 LTS and Windows 11","title":"如何雙啓動 Ubuntu 22.04 LTS 和 Windows 11","tag":"202206","desc":""},"relativePath":"202206/20220516 How to Dual Boot Ubuntu 22.04 LTS and Windows 11.md","filePath":"[post].md"}'),w={name:"202206/20220516 How to Dual Boot Ubuntu 22.04 LTS and Windows 11.md"};function b(d,t,m,c,g,U){const p=i("Link");return s(),e("div",null,[t[19]||(t[19]=u("h1",{id:"如何雙啓動-ubuntu-22-04-lts-和-windows-11",tabindex:"-1"},[n("如何雙啓動 Ubuntu 22.04 LTS 和 Windows 11 "),u("a",{class:"header-anchor",href:"#如何雙啓動-ubuntu-22-04-lts-和-windows-11","aria-label":"Permalink to “如何雙啓動 Ubuntu 22.04 LTS 和 Windows 11”"},"​")],-1)),t[20]||(t[20]=u("p",null,[u("img",{src:"https://img.linux.net.cn/data/attachment/album/202206/12/110546fff10ck07e2p0z2f.jpg",alt:""})],-1)),t[21]||(t[21]=u("p",null,"嗨，夥計們，在這篇指南中，我們將演示如何在 Windows 11 的之外配置 Ubuntu 22.04 LTS（Jammy Jellyfish）的雙啓動設置。",-1)),t[22]||(t[22]=u("p",null,"為使其能工作，你需要在你的計算機上已經安裝好了 Windows 11 。接下來，你將需要在你的硬盤驅動器上創建一個單獨的分區，你將在此分區上安裝 Ubuntu 22.04 。我們將包含這點知識，因此不要擔心。",-1)),t[23]||(t[23]=u("p",null,[u("strong",null,"前置條件：")],-1)),t[24]||(t[24]=u("p",null,"在設置雙啓動前，這些是你所需要的：",-1)),u("ul",null,[u("li",null,[t[1]||(t[1]=n("一個 Ubuntu 22.04 的可啓動 USB 驅動器，你可以轉到 ",-1)),o(p,{href:"https://releases.ubuntu.com/22.04/"},{default:r(()=>[...t[0]||(t[0]=[n("Ubuntu 22.04 下載頁面",-1)])]),_:1}),t[2]||(t[2]=n(" 來下載 Ubuntu 22.04 的 ISO 鏡像文件。在 ISO 鏡像文件到位後，拿一個 16GB USB 驅動器，並使用 Rufus 應用程序來使其可啓動。",-1))]),t[3]||(t[3]=u("li",null,"快速穩定的互聯網連接",-1))]),t[25]||(t[25]=a('<h3 id="步驟-1、在你的硬盤驅動器上創建一個可用的分區" tabindex="-1">步驟 1、在你的硬盤驅動器上創建一個可用的分區 <a class="header-anchor" href="#步驟-1、在你的硬盤驅動器上創建一個可用的分區" aria-label="Permalink to “步驟 1、在你的硬盤驅動器上創建一個可用的分區”">​</a></h3><p>正如介紹中所提到的，我們首先需要在硬盤驅動器上創建一個單獨的分區，我們將在其中安裝 Ubuntu 22.04 。</p><p>因此，通過按下 <code>Windows + R</code> 組合鍵來打開磁盤管理器實用程序。</p><p>在對話框中，輸入 <code>diskmgmt.msc</code> ，並按下回車鍵。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/diskmgmt-msc-command-windows11.png" alt=""></p><p><ruby>磁盤管理<rt>disk management</rt></ruby>控制台將顯示當前磁盤分區，如你將在下面所看到的一樣。我們將通過壓縮 “卷 E” 來創建一個用於安裝 Ubuntu 的分區。這在你的安裝過程中可能有所不同，但是隻需要跟着做，你就會理解其中的大體意思。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Disk-Management-Console-Windows11.png" alt=""></p><p>因此，在你想要壓縮的磁盤驅動器捲上點擊鼠標右鍵，並在彈出的菜單中選擇 <ruby>壓縮卷<rt>Shrink</rt></ruby> 選項。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Shrink-Volume-Windows11.png" alt=""></p><p>將會出現一個彈出對話框，如下所示。具體指定壓縮的控件大小（以 MB 為單位），並單擊 <ruby>壓縮卷<rt>Shrink</rt></ruby> 。</p><p>這是指定給 Ubuntu 22.04 安裝所用的空間。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Shrink-Volume-Size-Windows11.png" alt=""></p><p>在縮小磁盤空間後，它將顯示為 <ruby>未分配<rt>Unallocated</rt></ruby> 或 <ruby>可用空間<rt>Free Space</rt></ruby>，如圖所示。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Free-Space-Disk-Management-Console-Windows11.png" alt=""></p><p>隨着有了可用空間，現在將可啓動 USB 驅動器插入到你的 PC ，並重新啓動你的系統。此外，要確保訪問 BIOS 設置，並修改啓動優先級，來使 USB 驅動器成為第一優先級。保存 BIOS 更改並繼續啓動。</p><h3 id="步驟-2、開始安裝" tabindex="-1">步驟 2、開始安裝 <a class="header-anchor" href="#步驟-2、開始安裝" aria-label="Permalink to “步驟 2、開始安裝”">​</a></h3><p>在第一個屏幕中，你將得到如圖所示的 GRUB 菜單。選擇第一個選項 <ruby>嘗試或安裝 Ubuntu<rt>Try or Install Ubuntu</rt></ruby> ，並按下 <ruby>回車鍵<rt>ENTER</rt></ruby> 按鍵。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Select-Install-Ubuntu-Linux.png" alt=""></p><p>Ubuntu 22.04 將開始加載，如下所示。這最多需要一分鐘。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Ubuntu-22-04-Loading-Screen.png" alt=""></p><p>此後，安裝程序嚮導將彈出，向你提供兩個選項： <ruby>嘗試 Ubuntu<rt>Try Ubuntu</rt></ruby> 和 <ruby>安裝 Ubuntu<rt>Install Ubuntu</rt></ruby>。因為我們的使命是安裝 Ubuntu ，所以選擇後者。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Choose-Install-Ubuntu-Linux.png" alt=""></p><p>接下來，選擇你的首選鍵盤佈局，並單擊 <ruby>繼續<rt>Continue</rt></ruby> 按鈕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Keyboard-Layout-Ubuntu-22-04.png" alt=""></p><p>在 <ruby>更新和其它軟件<rt>Updates and Other Software</rt></ruby> 步驟中，選擇 <ruby>正常安裝<rt>Normal Installation</rt></ruby> 以便安裝 Ubuntu的 GUI 版本，通過勾選其它剩餘選項來允許下載更新和安裝第三方的針對於圖像、WIFI 硬件和其它實用程序的軟件包。</p><p>接下來，單擊 <ruby>繼續<rt>Continue</rt></ruby> 按鈕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Normal-Installation-Option-During-Ubuntu-22-04-Installation.png" alt=""></p><p>下一步提供兩個安裝選項。第一個選項 - <ruby>清除整個磁盤並安裝 Ubuntu<rt>Erase disk and install Ubuntu</rt></ruby> – 完全地擦除你的驅動器並安裝。但是由於這是一個雙啓動設置，這個選項對於你現有安裝的 Windows 系統來説會是災難性的。</p><p>因此，選擇 <ruby>其它選項<rt>Something else</rt></ruby>，單擊 <ruby>繼續<rt>Continue</rt></ruby> 按鈕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Something-else-ubuntu-installation.png" alt=""></p><p>分區表將顯示所有現有的磁盤分區。到目前為止，我們僅有 NTFS 分區和我們之前壓縮出來的可用分區。</p><p>針對 Ubuntu 22.04 ，我們將創建下面的分區：</p><ul><li><code>/boot</code>        –        1 GB</li><li><code>/home</code>        –        10 GB</li><li><code>/</code>            –        12 GB</li><li>交換分區        –         2 GB</li><li>EFI           –       300 MB</li></ul><p>為開始使用這些分區，單擊 <ruby>可用空間<rt>Free Space</rt></ruby>分區下面的 “+” 符號。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Select-Free-Space-for-Ubuntu-22-04-Installation.png" alt=""></p><p>如圖顯示填寫 <code>/boot</code> 分區的詳細信息，然後單擊 <ruby>確定<rt>OK</rt></ruby> 按鈕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Boot-Partition-Ubuntu-22-04-LTS.png" alt=""></p><p>接下來，具體指定 <code>/home</code> 分區，並單擊 <ruby>確定<rt>OK</rt></ruby> 按鈕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Home-Partition-For-Ubuntu-22-04.png" alt=""></p><p>接下來，定義 <code>/</code>（根）分區，並單擊 <ruby>確定<rt>OK</rt></ruby> 按鈕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Root-Partition-For-Ubuntu-22-04.png" alt=""></p><p>為定義交換空間，設置大小，並在 <ruby>使用為<rt>Use as</rt></ruby>：選項中選擇 <ruby>交換區域<rt>Swap area</rt></ruby>。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Swap-Area-Ubuntu-22-04.png" alt=""></p><p>最後，如果你正在使用 UEFI 啓動模式，那麼創建一個 EFI 系統分區。我們將分配 300MB 到 EFI 分區。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/EFI-System-Partition-Ubuntu-22-04.png" alt=""></p><p>下圖是一份我們的分區表的分區摘要：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Install-Now-Ubuntu-22-04.png" alt=""></p><p>為繼續安裝，單擊 <ruby>現在安裝<rt>Install Now</rt></ruby>。在下圖顯示的彈出窗口中，單擊 <ruby>繼續<rt>Continue</rt></ruby>來保存更改到磁盤。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Write-Changes-Disk-Ubuntu-22-04.png" alt=""></p><p>接下來，安裝程序嚮導將自動偵測出你的位置，只需要單擊 <ruby>繼續<rt>Continue</rt></ruby> 按鈕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Location-for-Ubuntu-22-04-Installation.png" alt=""></p><p>接下來，通過具體指定姓名、計算機的名稱和密碼來創建一個登錄用户。接下來單擊 <ruby>繼續<rt>Continue</rt></ruby> 按鈕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/UserName-Hostname-Ubuntu-22-04-lts-Installation.png" alt=""></p><p>此時，安裝程序嚮導將複製所有的 Ubuntu 文件和軟件包到手動創建的硬盤驅動器分區，並安裝必要的軟件包。</p><p>這個過程將需要很長一段時間，因此，要有耐心。在我們的實例中，它需要大約 30 分鐘。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Installation-Progress-Ubuntu-22-04.png" alt=""></p><p>在安裝過程完成後，單擊 <ruby>立刻重新啓動<rt>Restart Now</rt></ruby> 按鈕來重新啓動系統。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Restart-After-Ubuntu-22-04-LTS-Installation.png" alt=""></p><p>在這時，移除你的可啓動 USB 驅動器，並按下回車鍵。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Remove-Installation-Media-after-Ubuntu-22-04-Installation.png" alt=""></p><p>在系統重新啓動時，你將找到包括 Ubuntu 和 Windows 11 在內的各種選項。</p><p>選擇 “Ubuntu” 來啓動到你的新 Ubuntu 22.04 安裝。要啓動到 Windows 11，請選擇標有 <ruby>Windows 恢復環境<rt>Windows Recovery Environment</rt></ruby> 的條目。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Dual-Boot-Grub-Bootloader-Screen-Ubuntu-22-04.png" alt=""></p><p>就這樣。我們演示瞭如何雙啓動 Windows 11 和 Ubuntu 22.04。</p><hr>',65)),u("p",null,[t[5]||(t[5]=n("via: ",-1)),o(p,{href:"https://www.linuxtechi.com/dual-boot-ubuntu-22-04-and-windows-11/"},{default:r(()=>[...t[4]||(t[4]=[n("https://www.linuxtechi.com/dual-boot-ubuntu-22-04-and-windows-11/",-1)])]),_:1})]),u("p",null,[t[10]||(t[10]=n("作者：",-1)),o(p,{href:"https://www.linuxtechi.com/author/james/"},{default:r(()=>[...t[6]||(t[6]=[n("James Kiarie",-1)])]),_:1}),t[11]||(t[11]=n(" 選題：",-1)),o(p,{href:"https://github.com/lkxed"},{default:r(()=>[...t[7]||(t[7]=[n("lkxed",-1)])]),_:1}),t[12]||(t[12]=n(" 譯者：",-1)),o(p,{href:"https://github.com/robsean"},{default:r(()=>[...t[8]||(t[8]=[n("robsean",-1)])]),_:1}),t[13]||(t[13]=n(" 校對：",-1)),o(p,{href:"https://github.com/wxy"},{default:r(()=>[...t[9]||(t[9]=[n("wxy",-1)])]),_:1})]),u("p",null,[t[16]||(t[16]=n("本文由 ",-1)),o(p,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[14]||(t[14]=[n("LCTT",-1)])]),_:1}),t[17]||(t[17]=n(" 原創編譯，",-1)),o(p,{href:"https://linux.cn/"},{default:r(()=>[...t[15]||(t[15]=[n("Linux中國",-1)])]),_:1}),t[18]||(t[18]=n(" 榮譽推出",-1))])])}const S=l(w,[["render",b]]);export{x as __pageData,S as default};
